import itertools

def get_knight_moves(r, c, rows, cols):
    moves = []
    for dr, dc in [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            moves.append((nr, nc))
    return moves

def solve_game(rows, cols):
    # We want to find the max K such that Horst can guarantee K knights
    # This is a zero-sum game.
    # State: (horsts_knights, queenies_queens, turn)
    # turn: 0 for Horst, 1 for Queenie

    memo = {}

    def get_possible_knight_moves(knights, queens):
        possible = []
        for r in range(rows):
            for c in range(cols):
                if (r, c) not in knights and (r, c) not in queens:
                    # Check if this knight attacks any existing knights
                    attacks = False
                    for nr, nc in get_knight_moves(r, c, rows, cols):
                        if (nr, nc) in knights:
                            attacks = True
                            break
                    if not attacks:
                        possible.append((r, c))
        return possible

    def get_possible_queen_moves(knights, queens):
        possible = []
        for r in range(rows):
            for c in range(cols):
                if (r, c) not in knights and (r, c) not in queens:
                    possible.append((r, c))
        return possible

    def play(knights, queens, turn):
        state = (tuple(sorted(list(knights))), tuple(sorted(list(queens))), turn)
        if state in memo:
            return memo[state]

        if turn == 0: # Horst's turn
            possible = get_possible_knight_moves(knights, queens)
            if not possible:
                return len(knights)

            # Horst wants to maximize the final number of knights
            res = -1
            for move in possible:
                res = max(res, play(knights | {move}, queens, 1))
            memo[state] = res
            return res
        else: # Queenie's turn
            possible = get_possible_queen_moves(knights, queens)
            if not possible:
                return len(knights)

            # Queenie wants to minimize the final number of knights
            res = float('inf')
            for move in possible:
                res = min(res, play(knights, queens | {move}, 0))
            memo[state] = res
            return res

    return play(set(), set(), 0)

