def solve_cycle_game(n):
    memo = {}
    def play(picked, removed, turn):
        state = (picked, removed, turn)
        if state in memo: return memo[state]
        if turn == 0: # Horst
            possible = []
            for v in range(n):
                if v not in picked and v not in removed:
                    # Knight cannot attack any previously picked knights
                    if (v-1)%n not in picked and (v+1)%n not in picked:
                        possible.append(v)
            if not possible: return len(picked)
            res = max(play(picked | {move}, removed, 1) for move in possible)
            memo[state] = res
            return res
        else: # Queenie
            possible = []
            for v in range(n):
                if v not in picked and v not in removed:
                    possible.append(v)
            if not possible: return len(picked)
            res = min(play(picked, removed | {move}, 0) for move in possible)
            memo[state] = res
            return res
    return play(frozenset(), frozenset(), 0)

