def solve_graph_game(adj):
    memo = {}
    nodes = list(adj.keys())

    def play(knights, queens, turn):
        state = (frozenset(knights), frozenset(queens), turn)
        if state in memo: return memo[state]

        if turn == 0: # Horst
            possible = []
            for v in nodes:
                if v not in knights and v not in queens:
                    if all(neighbor not in knights for neighbor in adj[v]):
                        possible.append(v)
            if not possible: return len(knights)
            res = max(play(knights | {move}, queens, 1) for move in possible)
            memo[state] = res
            return res
        else: # Queenie
            possible = []
            for v in nodes:
                if v not in knights and v not in queens:
                    possible.append(v)
            if not possible: return len(knights)
            res = min(play(knights, queens | {move}, 0) for move in possible)
            memo[state] = res
            return res

    return play(set(), set(), 0)

